CREATE TABLE users(id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('employee','executor','admin')), department text NOT NULL);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE categories(name text PRIMARY KEY, assignee_id text REFERENCES users(id));
CREATE TABLE appeals(id text PRIMARY KEY, title text NOT NULL, description text NOT NULL, solution text NOT NULL DEFAULT '', kind text NOT NULL, category text NOT NULL, department text NOT NULL, priority text NOT NULL DEFAULT 'medium', status text NOT NULL DEFAULT 'new', author_id text NOT NULL REFERENCES users(id), assignee_id text REFERENCES users(id), parent_id text REFERENCES appeals(id), affected integer NOT NULL DEFAULT 1 CHECK(affected>0), expected_effect integer NOT NULL DEFAULT 0 CHECK(expected_effect>=0), actual_effect integer NOT NULL DEFAULT 0 CHECK(actual_effect>=0), result text NOT NULL DEFAULT '', due_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), confirmed_at timestamptz);
CREATE INDEX appeals_filters ON appeals(status,category,created_at DESC);
CREATE INDEX appeals_author ON appeals(author_id,created_at DESC);
CREATE INDEX appeals_assignee ON appeals(assignee_id,status);
CREATE INDEX appeals_parent ON appeals(parent_id);
CREATE TABLE comments(id bigserial PRIMARY KEY, appeal_id text NOT NULL REFERENCES appeals(id), user_id text NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX comments_appeal ON comments(appeal_id,created_at);
CREATE TABLE history(id bigserial PRIMARY KEY, appeal_id text NOT NULL REFERENCES appeals(id), user_id text NOT NULL REFERENCES users(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX history_appeal ON history(appeal_id,created_at);
CREATE TABLE votes(appeal_id text NOT NULL REFERENCES appeals(id), user_id text NOT NULL REFERENCES users(id), PRIMARY KEY(appeal_id,user_id));
CREATE TABLE attachments(id text PRIMARY KEY, appeal_id text NOT NULL REFERENCES appeals(id), name text NOT NULL, size bigint NOT NULL, content_type text NOT NULL);
CREATE TABLE notifications(id bigserial PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), appeal_id text NOT NULL REFERENCES appeals(id), body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_user ON notifications(user_id,created_at DESC);
